# Noncompliant: unnecessary conversion to list
for item in list(range(100)):
    print(item)

# Noncompliant: converting generator to list for iteration
def get_items():
    yield from range(10)

for item in list(get_items()):
    process(item)

# Noncompliant: converting dict.keys() to list for iteration
my_dict = {'a': 1, 'b': 2}
for key in list(my_dict.keys()):
    print(key)

