# Compliant: direct iteration over range
for item in range(100):
    print(item)

# Compliant: direct iteration over generator
def get_items():
    yield from range(10)

for item in get_items():
    process(item)

# Compliant: direct iteration over dict keys
my_dict = {'a': 1, 'b': 2}
for key in my_dict.keys():
    print(key)
